class Solution {
public:
    int maxXorSubsequences(vector<int>& nums) {
        int basis[31] = {};
        for (int x : nums) {
            for (int b = 30; b >= 0; --b) {
                if (!(x & (1 << b))) continue;
                if (!basis[b]) { basis[b] = x; break; }
                x ^= basis[b];
            }
        }
        int ans = 0;
        for (int b = 30; b >= 0; --b) ans = max(ans, ans ^ basis[b]);
        return ans;
    }
};
